const body = $input.all()[0]?.json?.body || $input.all()[0]?.json || {};
const papers = body.papers || [];
const question = body.question || 'What are the key findings, research gaps and emerging topics?';
const timestamp = body.timestamp || new Date().toISOString();

// Build comprehensive papersList with full content for LLM analysis
const papersList = papers.map((p, i) => {
  const fullText = p.content || p.abstract || '';
  const authors = (p.authors || []).join(', ') || 'Unknown';
  const year = p.year || 'N/A';

  return `=== PAPER ${i+1} ===\nTitle: ${p.title}\nAuthors: ${authors}\nYear: ${year}\nID: ${p.id}\n\nFull Content:\n${fullText}`;
}).join('\n\n');

return [{json: {
  papers,
  question,
  timestamp,
  papersList,
  chatInput: `Papers Data:\n${papersList}\n\n\nAnalysis Question:\n${question}`,
  papersCount: papers.length,
  papersInfo: papers.map(p => ({ id: p.id, title: p.title, year: p.year }))
}}];

const inputs = $input.all();

const parseCandidateText = (obj) => {
  if (!obj) return obj;
  const candidates = obj.candidates ?? (Array.isArray(obj) ? obj : null);
  if (candidates && candidates[0]?.content?.parts?.[0]?.text) {
    const text = candidates[0].content.parts[0].text;
    const m = text.match(/```json\s*([\s\S]*?)\s*```/);
    const jsonString = m ? m[1] : text;
    try { return JSON.parse(jsonString); } catch(e) { return obj; }
  }
  return obj;
};

// Combine all 4 module outputs from merge
const combined = {
  summarization: {},
  gapDetection: {},
  trendDetection: {},
  visualization: {},
  timestamp: new Date().toISOString(),
  status: 'completed'
};

// Parse each input from Merge node
for (let i = 0; i < inputs.length; i++) {
  const parsed = parseCandidateText(inputs[i]?.json || {});

  // Assign to appropriate module based on order
  if (i === 0) combined.summarization = parsed;
  else if (i === 1) combined.gapDetection = parsed;
  else if (i === 2) combined.trendDetection = parsed;
  else if (i === 3) combined.visualization = parsed;
}

return [{ json: combined }];

